// ============================================================
// i18n.js — 다국어(국제화) 엔진
// ============================================================
// 설계:
//  - HTML 요소에 data-i18n="key" (텍스트) 또는
//    data-i18n-attr="attr:key" (속성; 예: content:meta.description) 를 붙인다.
//  - 키에 대응하는 번역이 있으면 치환하고, 없으면 원문(한국어)을 그대로 둔다(안전한 폴백).
//  - 언어 선택 순서: localStorage → ?lang= → navigator.language → 기본(ko)
//  - 선택 시 localStorage 저장 + <html lang> + og:locale + 드롭다운 동기화 + URL ?lang 갱신
//
// 긴 교육용 본문은 점진적으로 키를 추가해 번역을 채운다.
// (키가 없는 요소는 한국어 원문이 그대로 보이므로 사이트가 깨지지 않는다.)

export const SUPPORTED = ["ko", "en", "ja", "es", "fr", "de"];
const DEFAULT_LANG = "ko";
const STORAGE_KEY = "vbe-lang";
const OG_LOCALE = { ko: "ko_KR", en: "en_US", ja: "ja_JP", es: "es_ES", fr: "fr_FR", de: "de_DE" };

// 번역 리소스. 키가 없으면 HTML 원문(한국어)이 노출된다.
// UI 골격(헤더·탭·엔진 상태·언어 이름)과 SEO 메타를 전 언어로 제공한다.
