    "js.vConsentOk": "with signature <b>(r,s)</b> · sighash <b>z</b> · public key <b>Q</b>: <span class=\"mono\">R′ = z·s⁻¹·G + r·s⁻¹·Q</span> → <b>R′.x == r</b> holds.",
