    "js.sig2Note": "The private key is secret, so it <b>never appears on screen</b>. The resulting signature is 64 bytes = <b>r</b> (first 32) ‖ <b>s</b> (last 32).",
    "js.sigR": "Signature r <span class=\"muted\">(first 32 bytes)</span>",
