    "js.sig3H": "3️⃣ Verify with the public key <span class=\"muted\">(no private key needed — anyone can)</span>",
    "js.sigTitle": "🔏 Digital signature &amp; verification <span class=\"pill-tag\">secp256k1 ECDSA</span>",
    "js.sigIntro": "Like real Bitcoin, <b>each input (UTXO being spent) is signed separately</b>. Each input takes \"the transaction contents + <b>which input is being spent now</b>\" as its message, hashes it with SHA-256 (→ sighash), then signs with the private key. That's why <b>every input has a different sighash and a different signature</b>.",
    "js.sigMulti": " (this transaction has <b>{n} inputs</b> → {n} cards)",
    "js.sigSingle": " (just 1 input this time — with more inputs you'd see more cards.)",
    "js.sigAsideSummary": "🔍 (b) Why does this verification equation prove \"unforgeability\"?",
    "js.sigAsideBody": "<p>The signer creates the signature with private key <b>d</b> and one-time <b>k</b>:</p><p class=\"mono small\">r = (k·G).x  ·  s = k⁻¹·(z + r·d)  mod n</p><p>The verifier computes <b>R′ = u₁·G + u₂·Q</b> (u₁=z·s⁻¹, u₂=r·s⁻¹) from public values only, <b>without the private key</b>. Substituting Q = d·G brings it back to <b>R′ = k·G</b>, and only then does <b>R′.x == r</b>.</p><ul class=\"tight\"><li>For the equation to hold, <b>this exact z (sighash)</b> must have been signed with <b>the d that produced Q</b>.</li><li>Change even one character of the transaction and z changes → <b>R′.x ≠ r</b> → rejected.</li><li>If someone else signs (different d·Q), it doesn't hold → rejected.</li></ul><p class=\"muted small\">Note: this demo (and modern Bitcoin) uses <b>RFC 6979 deterministic k</b>, so the <b>exact same</b> (private key · sighash) yields the same signature. Signatures look different per input because each input's message (sighash) differs.</p>",
