      "RustとWebAssemblyで作ったインタラクティブなビットコイン学習ツール。SHA-256ハッシュ、マイニング（プルーフ・オブ・ワーク）、UTXO、電子署名、ブロックチェーン、P2P合意、二重支払い・量子コンピューターの脅威まで、実際に触って学べます。",
