    "js.vConsentOk": "署名 <b>(r,s)</b>·sighash <b>z</b>·公開鍵 <b>Q</b> で <span class=\"mono\">R′ = z·s⁻¹·G + r·s⁻¹·Q</span> → <b>R′.x == r</b> が成立。",
    "js.vConsentBad": "署名がこのsighashと一致しません。",
    "js.vConsentSkip": "(a)で既に脱落したため確認まで進みません。この署名は署名者の鍵としては数学的に有効ですが、その鍵がコインの持ち主ではないので意味がありません。",
