    "js.sigQ": "公開鍵 Q <span class=\"muted\">（= 秘密鍵 d × G · 33バイト圧縮）</span>",
    "js.sig3H": "3️⃣ 公開鍵で検証 <span class=\"muted\">（秘密鍵なしで、誰でも）</span>",
    "js.sigTitle": "🔏 デジタル署名 &amp; 検証 <span class=\"pill-tag\">secp256k1 ECDSA</span>",
    "js.sigIntro": "実際のビットコインのように<b>入力（消費するUTXO）ごとに個別に署名</b>します。各入力は「取引内容 + <b>いまどの入力を使うか</b>」を原文としてSHA-256（→ sighash）し、秘密鍵で署名します。だから<b>入力ごとにsighashも署名も異なります</b>。",
    "js.sigMulti": "（この取引は入力<b>{n}個</b> → カード{n}枚）",
    "js.sigSingle": "（今回は入力1個 — 複数ならカードも複数になります。）",
    "js.sigAsideSummary": "🔍 (b) この検証式がなぜ「偽造不可の証明」になるの？",
    "js.sigAsideBody": "<p>署名者は秘密鍵<b>d</b>と使い捨ての<b>k</b>で署名を作ります:</p><p class=\"mono small\">r = (k·G).x  ·  s = k⁻¹·(z + r·d)  mod n</p><p>検証者は<b>秘密鍵なしで</b>公開値だけから <b>R′ = u₁·G + u₂·Q</b>（u₁=z·s⁻¹, u₂=r·s⁻¹）を計算します。Q = d·G を代入すると <b>R′ = k·G</b> に戻り、そのときだけ <b>R′.x == r</b>。</p><ul class=\"tight\"><li>等式が成り立つには<b>Qを作ったそのd</b>で<b>まさにこのz（sighash）</b>に署名した必要がある。</li><li>取引内容を1文字変えるだけでzが変わり → <b>R′.x ≠ r</b> → 拒否。</li><li>他人が署名すれば（別のd·Q）成り立たず → 拒否。</li></ul><p class=\"muted small\">参考: このデモ（および現代のビットコイン）は<b>RFC 6979の決定論的k</b>なので、<b>完全に同じ</b>（秘密鍵·sighash）なら署名も同じです。入力ごとに原文（sighash）が違うため署名も異なって見えるのです。</p>",
    "js.sigVerdictOk": "✅ 検証合格 — 入力{n}個すべてが (a) アドレス一致 + (b) 署名有効。取引が適用されました。",
