    "js.vConsent": "(b) Verificación de consentimiento",
    "js.vConsentOk": "con la firma <b>(r,s)</b> · sighash <b>z</b> · clave pública <b>Q</b>: <span class=\"mono\">R′ = z·s⁻¹·G + r·s⁻¹·Q</span> → se cumple <b>R′.x == r</b>.",
    "js.vConsentBad": "la firma no coincide con este sighash.",
