    "js.lockAddr": "dirección bloqueada",
    "js.sig1H": "1️⃣ Mensaje de esta entrada → SHA-256 → sighash",
    "js.sigHashBtn": "🔁 Pasa tú mismo este mensaje por SHA-256",
    "js.sigCalcLbl": "SHA-256 calculado en tu navegador",
    "js.sigCalcHint": "Pulsa el botón de arriba para calcularlo aquí mismo.",
    "js.sigEngineLbl": "sighash que el motor firmó realmente",
    "js.sig2H": "2️⃣ Firmar este sighash con la clave privada — {who}",
    "js.sig2Note": "La clave privada es secreta, así que <b>nunca aparece en pantalla</b>. La firma resultante son 64 bytes = <b>r</b> (primeros 32) ‖ <b>s</b> (últimos 32).",
    "js.sigR": "Firma r <span class=\"muted\">(primeros 32 bytes)</span>",
    "js.sigS": "Firma s <span class=\"muted\">(últimos 32 bytes)</span>",
    "js.sigQ": "Clave pública Q <span class=\"muted\">(= clave privada d × G · 33 bytes comprimida)</span>",
    "js.sig3H": "3️⃣ Verificar con la clave pública <span class=\"muted\">(sin clave privada — cualquiera puede)</span>",
    "js.sigTitle": "🔏 Firma digital &amp; verificación <span class=\"pill-tag\">secp256k1 ECDSA</span>",
    "js.sigIntro": "Como en el Bitcoin real, <b>cada entrada (UTXO gastado) se firma por separado</b>. Cada entrada toma como mensaje \"el contenido de la transacción + <b>qué entrada se gasta ahora</b>\", lo hashea con SHA-256 (→ sighash) y lo firma con la clave privada. Por eso <b>cada entrada tiene un sighash y una firma distintos</b>.",
    "js.sigMulti": " (esta transacción tiene <b>{n} entradas</b> → {n} tarjetas)",
    "js.sigSingle": " (esta vez solo hay 1 entrada — con más entradas verías más tarjetas.)",
    "js.sigAsideSummary": "🔍 (b) ¿Por qué esta ecuación de verificación demuestra la \"infalsificabilidad\"?",
    "js.sigAsideBody": "<p>El firmante crea la firma con la clave privada <b>d</b> y un <b>k</b> de un solo uso:</p><p class=\"mono small\">r = (k·G).x  ·  s = k⁻¹·(z + r·d)  mod n</p><p>El verificador calcula <b>R′ = u₁·G + u₂·Q</b> (u₁=z·s⁻¹, u₂=r·s⁻¹) solo con valores públicos, <b>sin la clave privada</b>. Al sustituir Q = d·G se vuelve a <b>R′ = k·G</b>, y solo entonces <b>R′.x == r</b>.</p><ul class=\"tight\"><li>Para que la ecuación se cumpla, <b>este mismo z (sighash)</b> debió firmarse con <b>el d que produjo Q</b>.</li><li>Cambia un solo carácter de la transacción y z cambia → <b>R′.x ≠ r</b> → rechazada.</li><li>Si firma otra persona (d·Q distintos), no se cumple → rechazada.</li></ul><p class=\"muted small\">Nota: esta demo (y el Bitcoin moderno) usa <b>k determinista RFC 6979</b>, así que con la <b>misma exacta</b> (clave privada · sighash) la firma es la misma. Las firmas se ven distintas por entrada porque el mensaje (sighash) de cada entrada difiere.</p>",
    "js.sigVerdictOk": "✅ Verificación superada — las {n} entradas cumplen (a) dirección coincidente + (b) firma válida. Transacción aplicada.",
    "js.sigVerdictBad": "🚫 Verificación fallida — {err} La transacción fue rechazada, así que las monedas siguen a salvo. 🔒",
    "js.sigInvalid": "La firma no es válida.",
    "js.forgeInvalid": "Introduce un atacante, una víctima y una cantidad válidos.",
    "js.forgeSame": "Si atacante y víctima son iguales, es solo una transacción propia. Prueba otro nombre.",
    "js.forgeFailPre": "Intento fallido: {err}",
