    "js.forgeRejected": "<b>🚫 ¡Robo rechazado!</b> <b>{attacker}</b> intentó apoderarse de {amt} BTC de <b>{victim}</b>, pero <b>sin la clave privada de {victim}</b> no tuvo más remedio que firmar con su propia clave. Mira cómo el <b>mismo pipeline de verificación 1·2·3</b> de abajo lo atrapa justo en <b>③-(a)</b>. 🔒",
