    "js.vConsentOk": "avec la signature <b>(r,s)</b> · sighash <b>z</b> · clé publique <b>Q</b> : <span class=\"mono\">R′ = z·s⁻¹·G + r·s⁻¹·Q</span> → <b>R′.x == r</b> est vérifié.",
