    "js.sigCalcLbl": "SHA-256 calculé dans votre navigateur",
    "js.sigCalcHint": "Cliquez sur le bouton ci-dessus pour le calculer ici même.",
    "js.sigEngineLbl": "sighash réellement signé par le moteur",
    "js.sig2H": "2️⃣ Signer ce sighash avec la clé privée — {who}",
    "js.sig2Note": "La clé privée est secrète, donc <b>elle n'apparaît jamais à l'écran</b>. La signature obtenue fait 64 octets = <b>r</b> (32 premiers) ‖ <b>s</b> (32 derniers).",
    "js.sigR": "Signature r <span class=\"muted\">(32 premiers octets)</span>",
    "js.sigS": "Signature s <span class=\"muted\">(32 derniers octets)</span>",
    "js.sigQ": "Clé publique Q <span class=\"muted\">(= clé privée d × G · 33 octets compressée)</span>",
    "js.sig3H": "3️⃣ Vérifier avec la clé publique <span class=\"muted\">(sans clé privée — n'importe qui peut)</span>",
    "js.sigTitle": "🔏 Signature numérique &amp; vérification <span class=\"pill-tag\">secp256k1 ECDSA</span>",
    "js.sigIntro": "Comme dans le vrai Bitcoin, <b>chaque entrée (UTXO dépensé) est signée séparément</b>. Chaque entrée prend comme message « le contenu de la transaction + <b>quelle entrée est dépensée maintenant</b> », le hache en SHA-256 (→ sighash) et le signe avec la clé privée. C'est pourquoi <b>chaque entrée a un sighash et une signature différents</b>.",
    "js.sigMulti": " (cette transaction a <b>{n} entrées</b> → {n} cartes)",
    "js.sigSingle": " (cette fois une seule entrée — avec plusieurs, vous verriez plusieurs cartes.)",
    "js.sigAsideSummary": "🔍 (b) Pourquoi cette équation de vérification prouve-t-elle « l'infalsifiabilité » ?",
    "js.sigAsideBody": "<p>Le signataire crée la signature avec la clé privée <b>d</b> et un <b>k</b> à usage unique :</p><p class=\"mono small\">r = (k·G).x  ·  s = k⁻¹·(z + r·d)  mod n</p><p>Le vérificateur calcule <b>R′ = u₁·G + u₂·Q</b> (u₁=z·s⁻¹, u₂=r·s⁻¹) uniquement à partir de valeurs publiques, <b>sans clé privée</b>. En substituant Q = d·G on retrouve <b>R′ = k·G</b>, et alors seulement <b>R′.x == r</b>.</p><ul class=\"tight\"><li>Pour que l'équation tienne, <b>ce z précis (sighash)</b> doit avoir été signé avec <b>le d qui a produit Q</b>.</li><li>Changez un seul caractère de la transaction et z change → <b>R′.x ≠ r</b> → refusée.</li><li>Si quelqu'un d'autre signe (d·Q différents), ça ne tient pas → refusée.</li></ul><p class=\"muted small\">Note : cette démo (et le Bitcoin moderne) utilise un <b>k déterministe RFC 6979</b>, donc avec la <b>même exacte</b> (clé privée · sighash) la signature est identique. Les signatures diffèrent par entrée parce que le message (sighash) de chaque entrée diffère.</p>",
    "js.sigVerdictOk": "✅ Vérification réussie — les {n} entrées satisfont (a) adresse concordante + (b) signature valide. Transaction appliquée.",
    "js.sigVerdictBad": "🚫 Vérification échouée — {err} La transaction a été refusée, les pièces restent en sécurité. 🔒",
