    "js.sigTitle": "🔏 Digitale Signatur &amp; Verifikation <span class=\"pill-tag\">secp256k1 ECDSA</span>",
    "js.sigIntro": "Wie im echten Bitcoin wird <b>jede Eingabe (verbrauchtes UTXO) einzeln signiert</b>. Jede Eingabe nimmt als Nachricht \"den Transaktionsinhalt + <b>welche Eingabe gerade verbraucht wird</b>\", hasht sie mit SHA-256 (→ sighash) und signiert mit dem privaten Schlüssel. Deshalb hat <b>jede Eingabe einen anderen sighash und eine andere Signatur</b>.",
