    "js.sigAsideBody": "<p>Der Signierer erstellt die Signatur mit dem privaten Schlüssel <b>d</b> und einem einmaligen <b>k</b>:</p><p class=\"mono small\">r = (k·G).x  ·  s = k⁻¹·(z + r·d)  mod n</p><p>Der Prüfer berechnet <b>R′ = u₁·G + u₂·Q</b> (u₁=z·s⁻¹, u₂=r·s⁻¹) nur aus öffentlichen Werten, <b>ohne privaten Schlüssel</b>. Setzt man Q = d·G ein, ergibt sich wieder <b>R′ = k·G</b>, und nur dann gilt <b>R′.x == r</b>.</p><ul class=\"tight\"><li>Damit die Gleichung aufgeht, muss <b>genau dieses z (sighash)</b> mit <b>dem d, das Q erzeugte</b>, signiert worden sein.</li><li>Ändere ein einziges Zeichen der Transaktion und z ändert sich → <b>R′.x ≠ r</b> → abgelehnt.</li><li>Signiert jemand anderes (anderes d·Q), geht es nicht auf → abgelehnt.</li></ul><p class=\"muted small\">Hinweis: Diese Demo (und das moderne Bitcoin) nutzt <b>deterministisches k nach RFC 6979</b>, sodass bei <b>exakt gleichem</b> (privater Schlüssel · sighash) auch die Signatur gleich ist. Die Signaturen sehen pro Eingabe anders aus, weil die Nachricht (sighash) jeder Eingabe verschieden ist.</p>",
