let current = DEFAULT_LANG;

export function getLang() {
  return current;
}

export function t(key, params) {
  let s = (T[current] && T[current][key]) || (T[DEFAULT_LANG] && T[DEFAULT_LANG][key]) || key;
  if (params) {
    for (const [k, v] of Object.entries(params)) s = s.replaceAll(`{${k}}`, v);
  }
  return s;
}

// 동적으로 생성된 DOM(innerHTML 주입 후)에 번역을 적용할 때 호출한다.
export function applyI18n(root) {
  applyDom(root);
}

function pickInitialLang() {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved && SUPPORTED.includes(saved)) return saved;

  const qs = new URLSearchParams(location.search).get("lang");
  if (qs && SUPPORTED.includes(qs)) return qs;

  const nav = (navigator.languages || [navigator.language || ""])
    .map((l) => String(l).toLowerCase().split("-")[0]);
  for (const code of nav) {
    if (SUPPORTED.includes(code)) return code;
  }
  return DEFAULT_LANG;
}

// 최초 1회, 요소의 원문(한국어) HTML/속성을 저장해 둔다.
// → 번역 키가 없거나 한국어로 되돌릴 때 원문을 복원할 수 있다.
const originals = new WeakMap();

function snapshot(el, kind, value) {
  let store = originals.get(el);
  if (!store) {
    store = {};
    originals.set(el, store);
  }
  if (!(kind in store)) store[kind] = value;
  return store[kind];
}

// data-i18n / data-i18n-attr 를 훑어 번역을 적용한다.
function applyDom(root = document) {
  root.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    const original = snapshot(el, "html", el.innerHTML);
    const val = T[current] && T[current][key];
    // 번역이 있으면 적용, 없으면 원문(한국어) 복원. <b> 등 마크업 포함이라 innerHTML 사용.
    el.innerHTML = val != null ? val : original;
  });
  root.querySelectorAll("[data-i18n-attr]").forEach((el) => {
    // "attr:key" 또는 여러 개 "a:k1;b:k2"
    el.getAttribute("data-i18n-attr")
      .split(";")
      .forEach((pair) => {
        const [attr, key] = pair.split(":").map((s) => s.trim());
        if (!attr) return;
        const original = snapshot(el, "attr:" + attr, el.getAttribute(attr) ?? el.dataset.tip);
        const val = T[current] && T[current][key];
        const out = val != null ? val : original;
        if (out == null) return;
        // 툴팁(.hint)은 앱 시작 시 title → data-tip 으로 옮겨진다(setupTooltips).
        // 옮겨진 뒤의 언어 전환은 data-tip 을 갱신해야 실제 말풍선에 반영된다.
        if (attr === "title" && el.dataset.tip !== undefined) {
          el.dataset.tip = out;
        } else {
          el.setAttribute(attr, out);
        }
      });
  });
}

const LANG_LABEL = { ko: "한국어", en: "English", ja: "日本語", es: "Español", fr: "Français", de: "Deutsch" };

function syncMeta() {
  document.documentElement.lang = current;
  const og = document.querySelector('meta[property="og:locale"]');
  if (og) og.setAttribute("content", OG_LOCALE[current] || "en_US");
  const label = document.getElementById("langBtnLabel");
  if (label) label.textContent = LANG_LABEL[current] || current;
  document.querySelectorAll("#langMenu [data-lang]").forEach((li) => {
    li.setAttribute("aria-selected", li.dataset.lang === current ? "true" : "false");
  });
}

export function setLang(lang, { persist = true, updateUrl = true } = {}) {
  if (!SUPPORTED.includes(lang)) return;
  current = lang;
  if (persist) localStorage.setItem(STORAGE_KEY, lang);
  if (updateUrl) {
    const url = new URL(location.href);
    url.searchParams.set("lang", lang);
    history.replaceState(null, "", url);
  }
  applyDom();
  syncMeta();
  document.dispatchEvent(new CustomEvent("i18n:changed", { detail: { lang } }));
}

// 앱 시작 시 1회 호출. 커스텀 드롭다운도 여기서 연결한다.
export function initI18n() {
  current = pickInitialLang();
  applyDom();
  syncMeta();

  const btn = document.getElementById("langBtn");
  const menu = document.getElementById("langMenu");
  if (!btn || !menu) return;

  const close = () => {
    menu.hidden = true;
    btn.setAttribute("aria-expanded", "false");
  };
  const open = () => {
    menu.hidden = false;
    btn.setAttribute("aria-expanded", "true");
  };

  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    menu.hidden ? open() : close();
  });
  menu.addEventListener("click", (e) => {
    const li = e.target.closest("[data-lang]");
    if (!li) return;
    setLang(li.dataset.lang);
    close();
  });
  document.addEventListener("click", (e) => {
    if (!menu.hidden && !e.target.closest("#langPicker")) close();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") close();
  });
}
